1	import { ChatContent, ChatMessage } from '@/models/chat';
2	import { CodexStreamEvent } from '@/models/codex-events';
3	import { stripLogTimestamps } from '@/services/claude-stream';
4	
5	/**
6	 * Pure helpers for the chat pipeline (no React, no react-native imports).
7	 * Extracted from useChat so the reliability-critical logic — shell command
8	 * building, transcript merging, auth-issue sniffing — is unit-testable.
9	 */
10	
11	export const DEBUG_SNIPPET_MAX = 240;
12	
13	export function shellQuote(value: string): string {
14	  return `'${value.replace(/'/g, "'\\''")}'`;
15	}
16	
17	export function safeTaskName(value: string): string {
18	  return value.replace(/[^A-Za-z0-9_.-]/g, '-').slice(0, 120);
19	}
20	
21	/**
22	 * Wrap a turn command so the sprite stays awake while it runs:
23	 * a sprite task (expire 5m) re-put every 60s, a stderr dot every 20s to keep
24	 * the log stream warm, and a cleanup trap that tears both down on exit.
25	 */
26	export function withSpriteTaskHeartbeat(command: string, taskName: string): string {
27	  const quotedTaskName = shellQuote(taskName);
28	  return [
29	    `TASK_NAME=${quotedTaskName}`,
30	    `TASK_EXPIRE=5m`,
31	    `sprite_task_api() { curl -sS --unix-socket /.sprite/api.sock -H "Content-Type: application/json" "$@" >/dev/null 2>&1 || true; }`,
32	    `sprite_task_put() { sprite_task_api -X PUT "http://sprite/v1/tasks/$TASK_NAME" -d "{\\"expire\\":\\"$TASK_EXPIRE\\"}"; }`,
33	    `sprite_task_delete() { sprite_task_api -X DELETE "http://sprite/v1/tasks/$TASK_NAME"; }`,
34	    'cleanup() { status=$?; trap - EXIT INT TERM; if [ -n "${LOG_HBEAT:-}" ]; then kill "$LOG_HBEAT" 2>/dev/null || true; wait "$LOG_HBEAT" 2>/dev/null || true; fi; if [ -n "${TASK_HBEAT:-}" ]; then kill "$TASK_HBEAT" 2>/dev/null || true; wait "$TASK_HBEAT" 2>/dev/null || true; fi; sprite_task_delete; exit "$status"; }',
35	    `trap cleanup EXIT INT TERM`,
36	    `sprite_task_put`,
37	    `(while true; do sleep 60; sprite_task_put; done) & TASK_HBEAT=$!`,
38	    `(while true; do sleep 20; printf . >&2; done) & LOG_HBEAT=$!`,
39	    command,
40	  ].join('; ');
41	}
42	
43	/**
44	 * App-server is a long-lived process, but mobile chat runs are one process per
45	 * turn. This tiny Node proxy forwards stdin/stdout and terminates app-server
46	 * after its terminal `turn/completed` notification. Keeping that lifecycle on
47	 * the sprite means a disconnected phone does not leave a heartbeat-backed
48	 * app-server running for hours.
49	 */
50	export function buildCodexAppServerCommand(): string {
51	  const source = [
52	    `const { spawn } = require('node:child_process')`,
53	    `const child = spawn('codex', ['app-server', '--stdio'], { stdio: ['pipe', 'pipe', 'inherit'] })`,
54	    `let buffer = ''`,
